package com.oldschoolnetwork.services.liteinstaller;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import com.oldschoolnetwork.certificates.RootCertificates;import com.oldschoolnetwork.lite.Transfers;import java.io.*;import java.util.*;import org.json.*;
public final class MainActivity extends Activity {
 private final Handler ui=new Handler();private TextView status;private List<JSONObject> releases;private List<File> apks;private boolean busy;private int next;
 public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.main);status=(TextView)findViewById(R.id.status);
  findViewById(R.id.ordinary).setOnClickListener(new View.OnClickListener(){public void onClick(View v){begin(false);}});
  findViewById(R.id.full).setOnClickListener(new View.OnClickListener(){public void onClick(View v){confirmFull();}});
  findViewById(R.id.certificates).setOnClickListener(new View.OnClickListener(){public void onClick(View v){certificates(false);}});
  findViewById(R.id.restore).setOnClickListener(new View.OnClickListener(){public void onClick(View v){certificates(true);}});
  findViewById(R.id.help).setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{startActivity(new Intent(MainActivity.this,com.oldschoolnetwork.lite.DocumentsActivity.class).putExtra("url","https://oldschoolnetwork.online/downloads/docs/full-install/"));}catch(Exception e){status.setText("oldschoolnetwork.online/downloads/docs/full-install/");}}});
  try{StringBuilder list=new StringBuilder("Android "+Build.VERSION.RELEASE+" · "+Build.CPU_ABI+"\n");for(JSONObject r:Payload.entries(this,true))list.append(r.getString("name")).append(" ").append(r.getString("version_name")).append('\n');((TextView)findViewById(R.id.payload)).setText(list);}catch(Exception error){status.setText("Signed payload is not prepared. "+error.getMessage());findViewById(R.id.ordinary).setEnabled(false);findViewById(R.id.full).setEnabled(false);}
 }
 private void confirmFull(){if(busy)return;StringBuilder message=new StringBuilder("Install selected ON Lite services into /system/app. Root and a restart are required. Recovery copies are saved before changes.\n");if(((CheckBox)findViewById(R.id.remove_google)).isChecked()){message.append("\nThe following selected legacy Google services will be removed. Apps depending on them may stop working:\n");for(GoogleComponents.Entry e:GoogleComponents.installed(this))message.append(e.label).append(" ( ").append(e.packageName).append(" )\n");}
  new AlertDialog.Builder(this).setTitle("Full Lite installation").setMessage(message.toString()).setNegativeButton("Cancel",null).setPositiveButton("Install with root",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){begin(true);}}).show();}
 private void begin(final boolean full){if(busy)return;busy=true;controls(false);status.setText("Verifying the signed payload…");final boolean store=((CheckBox)findViewById(R.id.choose_store)).isChecked(),roots=((CheckBox)findViewById(R.id.choose_certificates)).isChecked();final List<GoogleComponents.Entry> removals=full&&((CheckBox)findViewById(R.id.remove_google)).isChecked()?GoogleComponents.installed(this):Collections.<GoogleComponents.Entry>emptyList();
  new Thread(new Runnable(){public void run(){try{releases=Payload.entries(MainActivity.this,store);apks=Payload.prepare(MainActivity.this,releases);if(full){String recovery=SystemInstall.install(MainActivity.this,releases,apks,removals);message("Services staged. Recovery: "+recovery);if(roots)try{RootCertificates.install(MainActivity.this,new RootCertificates.Log(){public void write(String s){message(s);}});}catch(Exception error){message("Services were staged, but certificates were not installed: "+error.getMessage());}ui.post(new Runnable(){public void run(){finishWork("Full installation staged. Restart the device to activate the services.");}});}else{next=0;ui.post(new Runnable(){public void run(){installNext();}});}}catch(final Exception error){ui.post(new Runnable(){public void run(){finishWork("Installation did not finish: "+error.getMessage());}});}}},"on-lite-install").start();
 }
 private void installNext(){if(next>=releases.size()){finishWork("Ordinary installation complete. Certificates require the separate root installation option.");return;}try{final File file=apks.get(next);Transfers.makePublic(this,file);status.setText("Install "+releases.get(next).getString("name"));InstallGuard.update(this,"Installing "+releases.get(next).getString("name"));Uri uri=Build.VERSION.SDK_INT<24?Uri.fromFile(file):Uri.parse("content://"+getPackageName()+".apks/"+file.getName());startActivityForResult(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra("android.intent.extra.RETURN_RESULT",true),81);}catch(Exception e){finishWork("Android could not open this APK: "+e.getMessage());}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==81&&busy){try{JSONObject r=releases.get(next);if(Transfers.installed(this,r.getString("package_name"))<r.getInt("version_code")){finishWork("Installation was cancelled or failed. Previously installed apps were kept.");return;}next++;installNext();}catch(Exception e){finishWork(e.getMessage());}}}
 private void certificates(final boolean restore){if(busy)return;new AlertDialog.Builder(this).setTitle(restore?"Restore certificates?":"Install Mozilla roots?").setMessage(restore?"Restore the previous trust store from the saved recovery copy. Restart afterwards.":"Add verified Mozilla root certificates with a recovery copy. Root and a restart are required. This does not upgrade TLS, JavaScript or your browser engine.").setNegativeButton("Cancel",null).setPositiveButton(restore?"Restore":"Install",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){busy=true;controls(false);new Thread(new Runnable(){public void run(){try{RootCertificates.Log log=new RootCertificates.Log(){public void write(String s){message(s);}};if(restore)RootCertificates.restore(MainActivity.this,log);else RootCertificates.install(MainActivity.this,log);ui.post(new Runnable(){public void run(){finishWork("Certificate operation complete. Restart the device.");}});}catch(final Exception e){ui.post(new Runnable(){public void run(){finishWork(e.getMessage());}});}}},"on-lite-certificates").start();}}).show();}
 private void message(final String s){ui.post(new Runnable(){public void run(){if(!isFinishing())status.append("\n"+s);}});}
 private void finishWork(String message){busy=false;controls(true);status.append("\n"+message);}
 private void controls(boolean enable){if(enable)stopService(new Intent(this,InstallGuard.class));else startService(new Intent(this,InstallGuard.class));for(int id:new int[]{R.id.ordinary,R.id.full,R.id.certificates,R.id.restore,R.id.choose_store,R.id.choose_certificates,R.id.remove_google})findViewById(id).setEnabled(enable);findViewById(R.id.progress).setVisibility(enable?View.GONE:View.VISIBLE);findViewById(R.id.restore).setEnabled(enable&&RootCertificates.canRestore(this));}
 public void onBackPressed(){if(busy)new AlertDialog.Builder(this).setMessage("Wait for the current operation to finish.").setPositiveButton("OK",null).show();else super.onBackPressed();}
}
